float dts(vec2 xy, float shf, float shy, float scy, float scx) {
    float a = abs(sin(xy.x*scx+shf)/scy-xy.y+shy);
    float b = abs(sin(xy.x*scx+shf)/scy-xy.y+shy+2.0);
    float c = abs(sin(xy.x*scx+shf)/scy-xy.y+shy-2.0);
    return min(min(a,b),c);
}

float rnd(float x, float n) {
    return fract(1e4*sin(x*10.0+10.0*pow(1.0+x, 2.5)+n*(2.0+x)*(2.0+x)));
}

#define PI 3.1415926538

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    const float n = 25.0;
    float cf = 0.0;
    float a = atan(uv.y, uv.x)/PI;
    float l = length(uv);
    if(l<0.5) {
        cf=pow(0.5-l, 0.75);
    }
    for(float j=0.0;j<n;++j) {
        vec2 p = vec2(l, a);
        float d= dts(p, 
            /*shf*/PI*rnd(j,1.0)-(1.0+rnd(j,2.0)*2.0)*iTime,
            /*shy*/rnd(j,3.0)*2.0-1.0,
            /*scy*/3.5+3.0*rnd(j, 0.0),
            /*scx*/3.0+rnd(j,4.0)*5.0);
        d = pow(d,1.5)*300.0;
        d = (2.0+2.0/(l+0.2))/(d+1.0);
        cf += d/12.0*pow(l<2.0?2.0-l:0.0,0.7);
    }

    cf=clamp(cf*PI,0.0,PI);
    vec3 col;
    col.z = abs(sin(cf));
    col.y = 1.0-abs(cos(cf));
    col.x = abs(sin(cf)*cos(cf));

    fragColor = vec4(col,1.0);

}
